def transition(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
    """Return ``target`` if the transition is allowed, else raise."""
    if (source, target) in self.allowed_transitions:
        return target
    else:
        raise ValueError(f"Transition from {source} to {target} is not allowed.")
